mapper.select:
SELECT  FROM user_checkins
WHERE user_id = #{userId}
  AND is_removed = FALSE
AND activity_id = #{activityId}
AND trip_id = #{tripId}
AND place_id = #{placeId}
ORDER BY created_at DESC
LIMIT 1

SELECT FROM user_checkins WHERE visibility = 'PUBLIC' AND is_removed = FALSE AND user_id <> #{excludeUserId}
AND id IN ( SELECT own.id FROM user_checkins own LEFT JOIN places own_place ON own_place.id = own.place_id WHERE ST_DWithin(goroute_point(own.latitude, own.longitude), goroute_point(#{latitude}, #{longitude}), #{radiusKm} * 1000) AND (own_place.latitude IS NULL OR own_place.longitude IS NULL) UNION ALL SELECT at_place.id FROM places p JOIN user_checkins at_place ON at_place.place_id = p.id WHERE ST_DWithin(goroute_point(p.latitude, p.longitude), goroute_point(#{latitude}, #{longitude}), #{radiusKm} * 1000))
AND (has_photo, created_at, id) < (#{cursorHasPhoto}, #{cursorCreatedAt}, #{cursorId})
AND EXISTS ( SELECT 1 FROM places kp WHERE kp.id = user_checkins.place_id )
AND NOT EXISTS ( SELECT 1 FROM content_takedowns t WHERE t.content_type = 'CHECKIN' AND t.content_id = user_checkins.id AND t.restored_at IS NULL) ORDER BY has_photo DESC, created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT FROM user_checkins WHERE user_id = #{userId} AND is_removed = FALSE AND visibility = 'PUBLIC'
AND NOT EXISTS ( SELECT 1 FROM content_takedowns t WHERE t.content_type = 'CHECKIN' AND t.content_id = user_checkins.id AND t.restored_at IS NULL)
ORDER BY visited_at DESC, created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM user_checkins
WHERE user_id = #{userId}
  AND place_id = #{placeId}
  AND is_removed = FALSE

SELECT COUNT(*)
FROM user_checkins
WHERE user_id = #{userId}
  AND location_key = #{locationKey}
  AND is_removed = FALSE

SELECT id, entity_id AS checkin_id, url, capture_source AS source, position, caption AS title, description, taken_at AS captured_at, latitude, longitude, accuracy_meters, created_at FROM media_assets WHERE entity_type = 'USER_CHECKIN' AND entity_id IN
#{checkinId}
AND (asset_role IS NULL OR asset_role = 'PHOTO') AND deleted_at IS NULL ORDER BY entity_id, position

SELECT checkin_id FROM user_checkin_likes
WHERE user_id = #{userId} AND checkin_id IN
#{id}

SELECT 

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT DISTINCT checkin_id FROM user_checkin_location_history
WHERE checkin_id IN
#{id}
